import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '급여 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 마감 이후 상태: 마감취소 없이는 계산·집계·마감을 다시 할 수 없다
const CLOSED_STATUSES = ['마감', '전표처리'];
// 가정: 마감취소 뒤에는 이미 계산된 급여(calculated_at 있음)로 과세집계를 다시 할 수 있다
const AGGREGATE_FROM = ['계산완료', '과세집계완료', '마감취소'];

type Db = Parameters<Parameters<typeof transaction>[0]>[0];

function idOf(value: unknown, name: string): number {
  const text = String(value ?? '');
  if (!/^[0-9]{1,15}$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', `${name} 값이 올바르지 않습니다.`);
  }
  return Number(text);
}

async function lockPayday(db: Db, paydayId: number) {
  const rows = await db.query(
    'SELECT payday_id AS "paydayId", status, calculated_at AS "calculatedAt" FROM payday WHERE payday_id = CAST(:paydayId AS bigint) FOR UPDATE',
    { paydayId },
  );
  if (rows.length === 0) {
    throw new ApiError(404, 'PAYDAY_NOT_FOUND', '급여 지급일을 찾을 수 없습니다.');
  }
  return rows[0];
}

function rejectClosed(status: string) {
  if (CLOSED_STATUSES.includes(status)) {
    throw new ApiError(409, 'PAYDAY_CLOSED', '이미 마감된 지급일입니다. 마감취소 후 진행하세요.');
  }
}

@Controller('api/v1')
export class FnSfr02102Controller {
  @Post('/paydays/:paydayId/calculate')
  @HttpCode(200)
  async calculatePayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = idOf(req.params['paydayId'], 'paydayId');
    return transaction(async (db) => {
      const payday = await lockPayday(db, paydayId);
      rejectClosed(payday.status);
      const targets = await db.query(
        'SELECT COUNT(*) AS "count" FROM payroll WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      if (Number(targets[0].count) === 0) {
        throw new ApiError(422, 'PAYROLL_TARGET_EMPTY', '급여 대상 임직원이 없습니다.');
      }
      // 지급·공제 합계는 항목별 금액(payroll_item_amount)을 항목 구분별로 합산한다
      await db.execute(
        'UPDATE payroll p SET '
          + 'total_payment_amount = COALESCE((SELECT SUM(a.amount) FROM payroll_item_amount a JOIN pay_item i ON i.pay_item_id = a.pay_item_id WHERE a.payroll_id = p.payroll_id AND i.item_category = \'지급\'), 0), '
          + 'total_deduction_amount = COALESCE((SELECT SUM(a.amount) FROM payroll_item_amount a JOIN pay_item i ON i.pay_item_id = a.pay_item_id WHERE a.payroll_id = p.payroll_id AND i.item_category = \'공제\'), 0), '
          + 'updated_at = now() '
          + 'WHERE p.payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      await db.execute(
        'UPDATE payroll SET net_pay_amount = total_payment_amount - total_deduction_amount, updated_at = now() WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      const rows = await db.query(
        'UPDATE payday SET status = \'계산완료\', calculated_at = now(), tax_aggregated_at = NULL, updated_at = now() '
          + 'WHERE payday_id = CAST(:paydayId AS bigint) '
          + 'RETURNING payday_id AS "paydayId", status, calculated_at AS "calculatedAt"',
        { paydayId },
      );
      return rows[0];
    });
  }

  @Get('/payrolls')
  async listPayrolls(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const paydayId = idOf(query['paydayId'], 'paydayId');
    const pageText = String(query['page'] ?? '0');
    const sizeText = String(query['size'] ?? DEFAULT_SIZE);
    if (!/^[0-9]{1,9}$/.test(pageText) || !/^[0-9]{1,9}$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page 또는 size 값이 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    return transaction(async (db) => {
      const totals = await db.query(
        'SELECT COUNT(*) AS "total" FROM payroll WHERE payday_id = CAST(:paydayId AS bigint)',
        { paydayId },
      );
      const items = await db.query(
        'SELECT payroll_id AS "payrollId", employee_id AS "employeeId", '
          + 'total_payment_amount AS "totalPaymentAmount", total_deduction_amount AS "totalDeductionAmount", '
          + 'net_pay_amount AS "netPayAmount" '
          + 'FROM payroll WHERE payday_id = CAST(:paydayId AS bigint) '
          + 'ORDER BY employee_id, payroll_id LIMIT :size OFFSET :offset',
        { paydayId, size, offset: page * size },
      );
      return { items, page, size, total: Number(totals[0].total) };
    });
  }

  @Post('/paydays/:paydayId/aggregate-tax')
  @HttpCode(200)
  async aggregatePayrollTax(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = idOf(req.params['paydayId'], 'paydayId');
    return transaction(async (db) => {
      const payday = await lockPayday(db, paydayId);
      rejectClosed(payday.status);
      if (!AGGREGATE_FROM.includes(payday.status) || payday.calculatedAt == null) {
        throw new ApiError(409, 'PAYROLL_NOT_CALCULATED', '급여계산이 완료되지 않았습니다. 급여계산을 먼저 실행하세요.');
      }
      const sums = await db.query(
        'SELECT '
          + 'COALESCE(SUM(a.amount) FILTER (WHERE i.taxable_yn = true), 0) AS "taxableAmount", '
          + 'COALESCE(SUM(a.amount) FILTER (WHERE i.taxable_yn = false), 0) AS "nonTaxableAmount" '
          + 'FROM payroll_item_amount a '
          + 'JOIN payroll p ON p.payroll_id = a.payroll_id '
          + 'JOIN pay_item i ON i.pay_item_id = a.pay_item_id '
          + 'WHERE p.payday_id = CAST(:paydayId AS bigint) AND i.item_category = \'지급\'',
        { paydayId },
      );
      const rows = await db.query(
        'UPDATE payday SET status = \'과세집계완료\', tax_aggregated_at = now(), updated_at = now() '
          + 'WHERE payday_id = CAST(:paydayId AS bigint) '
          + 'RETURNING payday_id AS "paydayId", status',
        { paydayId },
      );
      return {
        paydayId: rows[0].paydayId,
        status: rows[0].status,
        taxableAmount: Number(sums[0].taxableAmount),
        nonTaxableAmount: Number(sums[0].nonTaxableAmount),
      };
    });
  }

  @Post('/paydays/:paydayId/close')
  @HttpCode(200)
  async closePayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = idOf(req.params['paydayId'], 'paydayId');
    return transaction(async (db) => {
      const payday = await lockPayday(db, paydayId);
      rejectClosed(payday.status);
      if (payday.status !== '과세집계완료') {
        throw new ApiError(409, 'TAX_AGGREGATION_REQUIRED', '과세집계가 완료되지 않았습니다. 과세집계를 먼저 실행하세요.');
      }
      const rows = await db.query(
        'UPDATE payday SET status = \'마감\', closed_at = now(), updated_at = now() '
          + 'WHERE payday_id = CAST(:paydayId AS bigint) '
          + 'RETURNING payday_id AS "paydayId", status',
        { paydayId },
      );
      return rows[0];
    });
  }

  @Post('/paydays/:paydayId/cancel-close')
  @HttpCode(200)
  async cancelClosePayday(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const paydayId = idOf(req.params['paydayId'], 'paydayId');
    return transaction(async (db) => {
      const payday = await lockPayday(db, paydayId);
      if (payday.status !== '마감') {
        throw new ApiError(409, 'PAYDAY_NOT_CLOSED', '마감 상태의 지급일만 마감취소할 수 있습니다.');
      }
      const rows = await db.query(
        'UPDATE payday SET status = \'마감취소\', updated_at = now() '
          + 'WHERE payday_id = CAST(:paydayId AS bigint) '
          + 'RETURNING payday_id AS "paydayId", status',
        { paydayId },
      );
      return rows[0];
    });
  }
}

