import { useState } from 'react';
import { call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles, Form, Field, LookupSelect, RefName } from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const SIZE = 20;

interface Action {
  key: string;
  label: string;
  path: string;
  guide: string;
  done: string;
  danger?: boolean;
  allowed: (status: string) => boolean;
}

const ACTIONS: Action[] = [
  {
    key: 'calculate',
    label: '급여계산',
    path: 'calculate',
    guide: '선택한 지급일의 급여 대상 임직원별 지급·공제 항목을 계산합니다.',
    done: '급여계산을 완료했습니다.',
    allowed: (s) => s !== '마감' && s !== '전표처리',
  },
  {
    key: 'aggregate',
    label: '과세집계',
    path: 'aggregate-tax',
    guide: '계산이 끝난 급여의 과세·비과세 지급 금액을 집계합니다.',
    done: '과세집계를 완료했습니다.',
    allowed: (s) => s === '계산완료' || s === '과세집계완료' || s === '마감취소',
  },
  {
    key: 'close',
    label: '마감',
    path: 'close',
    guide: '마감하면 마감취소 전까지 급여를 수정할 수 없습니다.',
    done: '마감했습니다.',
    allowed: (s) => s === '과세집계완료',
  },
  {
    key: 'cancel',
    label: '마감취소',
    path: 'cancel-close',
    guide: '마감된 급여를 다시 수정할 수 있도록 마감을 취소합니다.',
    done: '마감을 취소했습니다.',
    danger: true,
    allowed: (s) => s === '마감',
  },
];

export default function FnSfr02102Page({ role, notify }: PageProps) {
  const [input, setInput] = useState<number | string>('');
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [action, setAction] = useState<Action | null>(null);
  const [result, setResult] = useState<Row | null>(null);
  const [statuses, setStatuses] = useState<Record<string, string>>({});

  const { data, error, reload } = useData<Page>(async () => {
    if (paydayId === '') {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/payrolls', role, undefined, { paydayId, page, size: SIZE });
  }, [paydayId, page, role]);

  const items = data ? data.items : [];
  const total = data ? data.total : 0;
  const known = paydayId === '' ? undefined : statuses[String(paydayId)];

  const sumOf = (key: string) => items.reduce((acc, row) => acc + Number(row[key] ?? 0), 0);

  const search = () => {
    if (input === '') {
      notify('급여 지급일을 선택하세요.');
      return;
    }
    setResult(null);
    setPage(0);
    if (input === paydayId) {
      reload();
    }
    setPaydayId(input);
  };

  const reset = () => {
    setInput('');
    setPaydayId('');
    setPage(0);
    setResult(null);
  };

  const open = (next: Action) => {
    if (paydayId === '') {
      notify('급여 지급일을 선택하고 조회한 뒤 진행하세요.');
      return;
    }
    setAction(next);
  };

  const submit = async () => {
    if (!action) {
      return;
    }
    const res = await call<Row>('POST', `/paydays/${paydayId}/${action.path}`, role, {});
    setResult(res);
    setStatuses((prev) => ({ ...prev, [String(paydayId)]: String(res.status) }));
    notify(action.done);
    setAction(null);
    reload();
  };

  const columns: Column[] = [
    { key: 'employeeId', label: '임직원', render: (row) => <RefName table="employee" role={role} value={row.employeeId} /> },
    { key: 'totalPaymentAmount', label: '지급 합계', render: (row) => <Num value={row.totalPaymentAmount} /> },
    { key: 'totalDeductionAmount', label: '공제 합계', render: (row) => <Num value={row.totalDeductionAmount} /> },
    { key: 'netPayAmount', label: '실수령액', render: (row) => <Num value={row.netPayAmount} /> },
  ];

  const resultItems: [string, React.ReactNode][] = result
    ? [
        ['급여 지급일', <RefName table="payday" role={role} value={result.paydayId} />],
        ['처리 상태', <Badge value={result.status} />],
      ]
    : [];
  if (result && result.calculatedAt !== undefined) {
    resultItems.push(['급여계산 완료 시각', <DateText value={result.calculatedAt} time />]);
  }
  if (result && result.taxableAmount !== undefined) {
    resultItems.push(['과세 집계 금액', <Num value={result.taxableAmount} />]);
    resultItems.push(['비과세 집계 금액', <Num value={result.nonTaxableAmount} />]);
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>급여 현황</h2>
        <Tiles
          items={[
            ['급여 대상(명)', <Num value={total} />],
            ['지급 합계(현재 쪽)', <Num value={sumOf('totalPaymentAmount')} />],
            ['공제 합계(현재 쪽)', <Num value={sumOf('totalDeductionAmount')} />],
            ['실수령 합계(현재 쪽)', <Num value={sumOf('netPayAmount')} />],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>급여계산 결과</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="급여 지급일 ID" required>
            <LookupSelect table="payday" role={role} value={input} onChange={setInput} placeholder="지급일 선택" />
          </Field>
        </Filters>
        <Band total={total} />
        {error ? <p>{error}</p> : null}
        <DataTable columns={columns} rows={items} empty="급여계산 결과가 없습니다." />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리</h2>
        <p>현재 상태: {known ? <Badge value={known} /> : '처리 후 표시됩니다.'}</p>
        <div>
          {ACTIONS.filter((item) => !known || item.allowed(known)).map((item) => (
            <button key={item.key} type="button" onClick={() => open(item)}>
              {item.label}
            </button>
          ))}
        </div>
        {result && String(result.paydayId) === String(paydayId) ? <Pairs items={resultItems} /> : null}
      </section>

      {action ? (
        <Drawer title={action.label} onClose={() => setAction(null)}>
          <Form onSubmit={submit} submit={action.label} danger={action.danger} note={action.guide}>
            <Field label="급여 지급일 ID" wide>
              <RefName table="payday" role={role} value={paydayId} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
